import {fixture} from './b033-runtime.mjs';
import {createApp} from '../../apps/api/src/app.ts';
import {assertSchema} from '../../packages/contracts/src/index.mjs';
import {registry} from '../../packages/operation-registry/src/index.mjs';
const check=(v,m)=>{if(!v)throw Error(m);};
export async function runChecks(client,runtime,test){
 const f=await fixture(client,runtime,1),app=await createApp(f.auth,{localOps:{auth:f.auth,privateRoot:f.byteRoot}}),base=await createApp(f.auth);
 const call=async(url,options={})=>{const r=await app.inject({method:'GET',url,...options});check(r.headers['cache-control']==='no-store'&&r.headers['x-content-type-options']==='nosniff'&&r.headers['content-type'].includes('application/json'),'safe headers');const b=r.json();assertSchema(r.statusCode===200?'success-envelope.json':'error-envelope.json',b);check(b.requestId===r.headers['x-request-id'],'request ID bound');return {status:r.statusCode,body:b};};
 try{
 await test('B035-default-off-live-ready',async()=>{check((await base.inject('/api/v1/health/live')).statusCode===404,'default off');const live=await call('/api/v1/health/live'),ready=await call('/api/v1/health/ready');check(live.body.data.live&&ready.body.data.ready&&!ready.body.data.persistentWriteVerified,'honest probes');return {defaultOff:true,dbAndDirectoryProbe:true,persistenceProof:false};});
 await test('B035-readiness-maintenance-generation-storage-redaction',async()=>{for(const fault of ['maintenance','generation','directory']){const ops=fault==='directory'?await createApp(f.auth,{localOps:{auth:f.auth,privateRoot:f.byteRoot+'/missing-private-fixture'}}):app;try{if(fault==='maintenance')await f.auth.c.control.updateOne({_id:'server'},{$set:{maintenance:true}});if(fault==='generation')await f.auth.c.control.updateOne({_id:'server'},{$set:{serverGeneration:crypto.randomUUID()}});const r=await ops.inject('/api/v1/health/ready');check(r.statusCode===503,'dependency unavailable');assertSchema('error-envelope.json',r.json());check(!r.body.includes(f.byteRoot)&&!r.body.includes('mongodb')&&!r.body.includes('stack'),'redaction');check((await ops.inject('/api/v1/health/live')).statusCode===200,'liveness distinct');}finally{await f.auth.c.control.updateOne({_id:'server'},{$set:{maintenance:false,serverGeneration:f.generation}});if(ops!==app)await ops.close();}}return {maintenance:true,generation:true,missingDirectory:true,safe503:true};});
 await test('B035-public-registry-bounds-no-enable',async()=>{const cap=await call('/api/v1/capabilities');check(!cap.body.data.publicAuthEnabled&&!cap.body.data.productAdaptersEnabled&&!Object.keys(cap.body.data.limits).some(k=>k.startsWith('perAccount')),'public projection');const all=[];let offset=0;while(offset!==null){const r=await call('/api/v1/operations?limit=100&offset='+offset);all.push(...r.body.data.items);offset=r.body.data.nextOffset;}check(all.length===registry.operations.length&&all.every((o,i)=>o.availability===registry.operations[i].capability.status),'registry authority');for(const url of ['/api/v1/operations?limit=101','/api/v1/operations?offset=-1','/api/v1/capabilities?ownerId=x'])check((await call(url)).status===422,'strict query');return {operations:all.length,registryUnchanged:true,strictBounds:true};});
 await test('B035-compatibility-session-no-release-claim',async()=>{check((await call('/api/v1/compatibility')).status===401,'private generation');const r=await call('/api/v1/compatibility',{headers:{cookie:'__Host-dashboard_session='+f.token}});check(r.body.data.serverGeneration===f.generation&&!r.body.data.releaseWindowVerified,'actual generation, no release claim');return {authenticated:true,releaseWindowVerified:false};});
 await test('B035-shared-registration-errors',async()=>{check((await call('/api/v1/unknown-private')).status===404,'JSON404');check((await call('/api/v1/health/live',{headers:{origin:'https://foreign.example.test'}})).status===403,'origin inherited');const r=await app.inject({method:'POST',url:'/api/v1/auth/logout',payload:{}});check(r.statusCode===403,'CSRF inherited');let rejected=false;try{await createApp(f.auth,{localOps:{auth:{},privateRoot:f.byteRoot}});}catch{rejected=true;}check(rejected,'shared authority');return {unknownJSON:true,originCSRFIntact:true,authorityMismatchHeld:true};});
 }finally{await app.close();await base.close();}
}
